  };
  var dm = {};
  ((plan && plan.entscheidungen) || []).forEach(function (d) { if (!dm[d.anlagen_id]) dm[d.anlagen_id] = d; });
  var aus = { data: [], eintraege: [], hinweise: [] };
  (anlagen || []).forEach(function (a) {
    var w = laText(a.versandstatus_klaeren);
