// Sperren aus Antworten schreibt "Antworten einordnen" sofort, VOR dem Blatt und vor jedem Versand (ein Abbruch danach
// verliert keinen Widerspruch).
function sperrDatenZeilen(ergebnisse, lauf, k) {
